"""ST statement coverage (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class StmtsTests(unittest.TestCase):

    def test_001_if_basic(self):
        source = """\
FUNCTION C01If : INT
VAR_INPUT V : INT; END_VAR
IF V > 0 THEN
C01If := 1;
END_IF;
END_FUNCTION
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('int16_t C01If(', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('pub fn C01If(', rust_result.output)

    def test_002_if_elsif_else(self):
        source = """\
FUNCTION C02If : INT
VAR_INPUT V : INT; END_VAR
IF V < 0 THEN
C02If := -1;
ELSIF V = 0 THEN
C02If := 0;
ELSE
C02If := 1;
END_IF;
END_FUNCTION
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('else if', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('else if', rust_result.output)

